with unpacked as (select id, host, log_ts, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, get_json_object(payload_json, '$.duration') as duration_text, context['trace'] as trace, coalesce(context['region'], 'none') as region_or_default, context['region'] as region from app_logs) select id, log_ts, region_or_default, region, lead(retry_count, 1) over (partition by host order by retry_count, id) as next_retry_count, ntile(5) over (partition by host order by retry_count desc, id) as retry_count_bucket from unpacked where retry_count <> 1
